// Validate payload — runs once. The webhook already checked the shared secret; this checks
// the shape so a bad request is answered with 400 before any work starts.
const body = $input.first().json.body || {};
const errors = [];
const STYLES = ['minimal', 'immersive'];
const AUDIENCES = ['agent', 'internal', 'client', 'mixed'];
const LANGUAGES = ['en', 'es'];
const s = (v) => (typeof v === 'string' ? v.trim() : '');

if (!/^\d{8}-\d{6}-[0-9a-f]{6}$/.test(s(body.jobId))) errors.push('jobId is missing or malformed');
if (!s(body.title)) errors.push('title is required');
if (!STYLES.includes(body.style)) errors.push('style must be minimal or immersive');
if (!AUDIENCES.includes(body.audience)) errors.push('audience is not one of agent, internal, client, mixed');
if (!LANGUAGES.includes(body.language)) errors.push('language must be en or es');
if (!s(body.destination)) errors.push('destination is required');
if (s(body.text).length < 200) {
  errors.push('text is too short to plan from (the PDF may be a scan)');
}

return [{ json: { ok: errors.length === 0, errors, jobId: s(body.jobId) } }];

// Context — runs once. Everything later nodes need about this job, in one place, so
// expressions read `$('Context').first().json.x` instead of digging into the webhook body.
const body = $('Webhook').first().json.body || {};
const cfg = $('Config').first().json;
const s = (v) => (typeof v === 'string' ? v.trim() : '');
const canvaEnabled = String(cfg.CANVA_ENABLED).toLowerCase() === 'true';

return [
  {
    json: {
      jobId: s(body.jobId),
      title: s(body.title),
      style: body.style,
      audience: body.audience,
      language: body.language,
      destination: s(body.destination),
      clientName: s(body.clientName),
      travelDates: s(body.travelDates),
      travelers: s(body.travelers),
      notes: s(body.notes),
      textLow: body.textLow === true,
      pageCount: Number(body.pageCount) || 0,
      textChars: Number(body.textChars) || 0,
      textLength: s(body.text).length,
      // dryRun skips Canva; the app never sends it, curl tests and the kill switch do.
      dryRun: body.dryRun === true || !canvaEnabled,
      force: body.force === true,
      appUrl: String(cfg.TOOLS_APP_URL || '').replace(/\/+$/, ''),
      anthropicUrl: String(cfg.ANTHROPIC_URL || 'https://api.anthropic.com/v1/messages'),
      pexelsUrl: String(cfg.PEXELS_URL || 'https://api.pexels.com/v1/search'),
      canvaUrl: String(cfg.CANVA_URL || 'https://api.canva.com/rest/v1'),
      model: String(cfg.CLAUDE_MODEL || 'claude-opus-5'),
      effort: String(cfg.CLAUDE_EFFORT || 'medium'),
    },
  },
];

// Can it run? — runs once. A job that is already running or finished is not run
// again unless the caller says `force`; re-posting a webhook must be harmless.
const job = $input.first().json;
const ctx = $('Context').first().json;
const run = ['queued', 'failed'].includes(job.status) || ctx.force === true;
return [{ json: { run, status: job.status } }];

// Asset index — runs once. Today a stub: no approved library exists yet, so the
// planner is told there are no assets and the resolver never finds a match.
//
// When the Zoho WorkDrive indexer lands, this node reads
// `presentations/index/workdrive-assets.json` from the bucket (or calls the app for it) and
// returns the same shape, filtered to the job's destination and capped at 300 entries:
//   { assets: [{ id, filename, destination, entity_type, entities, tags, orientation, url }] }
// Nothing downstream changes.
const ctx = $('Context').first().json;
return [{ json: { assets: [], source: 'stub', destination: ctx.destination, generatedAt: new Date().toISOString() } }];

// Validate manifest — runs once. Parses Claude's answer and checks the business rules the
// schema cannot express. Attempt 1 is strict and reports errors for a retry; attempt 2
// repairs what it safely can (shortens copy, drops extras) and only fails on what it cannot.
