const SOFT = ATTEMPT >= 2;
const LIMITS = {"eyebrow":24,"cover_title":42,"title":60,"subtitle":90,"day_label":12,"body_immersive":280,"body_minimal":420,"meta_items":5,"meta_item":40,"cards":6,"card_title":32,"card_body":120,"options":3,"stops":7,"list_items":8,"list_item":60,"cta":60};
