const LAYOUTS = ["full_bleed_hero_with_left_copy","split_photo_text","asymmetric_two_photo_editorial","timeline_route","information_cards","hotel_comparison","closing_story"];
const TYPES = ["cover","overview","route","itinerary_day","accommodation","inclusions","closing"];
const DEFAULT_LAYOUT = {"cover":"full_bleed_hero_with_left_copy","overview":"split_photo_text","route":"timeline_route","itinerary_day":"split_photo_text","accommodation":"hotel_comparison","inclusions":"information_cards","closing":"closing_story"};
