  c.cta = checkStr(slide, 'cta', c.cta, LIMITS.cta);
  c.meta = checkList(slide, 'meta', c.meta, LIMITS.meta_items, LIMITS.meta_item);
  c.included = checkList(slide, 'included', c.included, LIMITS.list_items, LIMITS.list_item);
  c.excluded = checkList(slide, 'excluded', c.excluded, LIMITS.list_items, LIMITS.list_item);
  c.stops = checkList(slide, 'stops', c.stops, LIMITS.stops, 0);
  c.options = checkList(slide, 'options', c.options, LIMITS.options, 0);
  c.cards = checkList(slide, 'cards', c.cards, LIMITS.cards, 0);
  if (Array.isArray(c.cards)) {
    c.cards = c.cards.map((card) => ({ ...card, title: checkStr(slide, 'card title', card.title, LIMITS.card_title), body: checkStr(slide, 'card body', card.body, LIMITS.card_body) }));
  }
  if (!c.title) errors.push(`${slide.id}: title is required`);
  slide.copy = c;

  // Assets: counts and the source policy.
  let photos = 0, decoratives = 0;
  const assets = [];
  for (const a of slide.assets || []) {
    if (a.purpose === 'decorative_element') {
      if (decoratives++ >= 1) { warnings.push(`${slide.id}: extra decorative element dropped`); continue; }
    } else if (photos++ >= 3) { warnings.push(`${slide.id}: more than three photos; extras dropped`); continue; }

    const named = a.subject_kind === 'named_property' || a.subject_kind === 'brand_element';
    if (a.source === 'workdrive') {
      const match = String(a.asset_match || '').toLowerCase();
      if (!match || !known.has(match)) {
        a.source = named ? 'placeholder' : 'pexels';
        warnings.push(`${slide.id}: "${a.asset_match || '?'}" is not in the asset index; using ${a.source}`);
      }
    }
    if (named && a.source === 'pexels') {
      if (SOFT) { a.source = 'placeholder'; warnings.push(`${slide.id}: a named property cannot use a stock photo; placeholder used`); }
      else errors.push(`${slide.id}: ${a.purpose} is a named property and must not use pexels`);
    }
    if (a.source === 'pexels' && !a.fallback_query) {
      if (SOFT) { a.source = 'placeholder'; warnings.push(`${slide.id}: pexels asset without a query; placeholder used`); }
      else errors.push(`${slide.id}: ${a.purpose} uses pexels but has no fallback_query`);
    }
    assets.push(a);
  }
  slide.assets = assets;
});

if (slides[0].type !== 'cover') errors.push('the first slide must be the cover');
if (slides[slides.length - 1].type !== 'closing') errors.push('the last slide must be the closing slide');
if (ctx.style === 'immersive' && slides[0].layout !== 'full_bleed_hero_with_left_copy') {
  if (SOFT) { slides[0].layout = 'full_bleed_hero_with_left_copy'; warnings.push('cover layout set to the full-bleed hero'); }
  else errors.push('an immersive cover must use full_bleed_hero_with_left_copy');
}
for (let i = 2; i < slides.length; i++) {
  if (slides[i].layout === slides[i - 1].layout && slides[i].layout === slides[i - 2].layout) {
    const msg = `slides ${slides[i - 2].id}, ${slides[i - 1].id}, ${slides[i].id} use the same layout three times in a row`;
    if (SOFT) warnings.push(msg); else errors.push(msg);
    break;
  }
}

m.slides = slides;
out.manifest = m;
out.valid = errors.length === 0;
return [{ json: out }];

// Final manifest — runs once. Whichever validation produced a usable manifest wins: the
// second attempt if it ran, otherwise the first. Later nodes read
// `$('Final manifest').first().json.manifest` and never care which path was taken.
let v = null;
try {
  v = $('Validate manifest (2)').first().json;
} catch (e) {
  v = null;
}
if (!v || !v.valid) v = $('Validate manifest').first().json;
if (!v.valid) throw new Error('No valid manifest: ' + v.errors.join('; '));

const usage = v.usage || {};
return [
  {
    json: {
      manifest: v.manifest,
      warnings: v.warnings || [],
      meta: {
        model: v.model || $('Context').first().json.model,
        usage,
        cacheRead: usage.cache_read_input_tokens || 0,
        attempts: v.attempt,
      },
    },
  },
];

// Flatten requirements — runs once, returns one item per asset the plan asks for.
//
// A layout's purpose decides the orientation and the smallest acceptable width; a hero
// photograph stretched across the slide needs far more pixels than a card thumbnail.
const m = $('Final manifest').first().json.manifest;

function hint(layout, purpose) {
  if (purpose === 'decorative_element') return { orientation: 'landscape', minWidth: 400 };
  if (layout === 'full_bleed_hero_with_left_copy' || layout === 'closing_story') return { orientation: 'landscape', minWidth: 1920 };
  if (layout === 'asymmetric_two_photo_editorial') {
    return purpose === 'primary_photo' ? { orientation: 'landscape', minWidth: 1600 } : { orientation: 'portrait', minWidth: 1000 };
  }
  if (layout === 'split_photo_text') return { orientation: 'landscape', minWidth: 1400 };
  return { orientation: 'landscape', minWidth: 1200 };
}

const items = [];
for (const slide of m.slides) {
  for (const a of slide.assets || []) {
    const h = hint(slide.layout, a.purpose);
    items.push({
      json: {
        order: items.length,
        slideId: slide.id,
        purpose: a.purpose,
        source: a.source,
        subject_kind: a.subject_kind,
        asset_match: a.asset_match || '',
        query: a.fallback_query || '',
        orientation: a.orientation || h.orientation,
        minWidth: h.minWidth,
      },
    });
  }
}

// A node with no input items never runs, and everything after it would be skipped. A deck
// with no photos at all still has to reach the compiler, so emit a marker item instead.
if (items.length === 0) items.push({ json: { order: 0, none: true } });
return items;

// Route assets — runs once over all requirement items. The pluggable first step of the
// resolver: look for an approved asset, then decide where the photo comes from.
//
// Order of precedence, from the business rules: an approved library match wins; a named
// property or brand element with no match gets the branded placeholder (never a stock
// photo, even if the planner asked for one); anything generic goes to Pexels.
const index = ($('Asset index').first().json || {}).assets || [];
const byName = new Map();
for (const a of index) {
  for (const key of [a.filename, a.id]) if (key) byName.set(String(key).toLowerCase(), a);
}
const normalize = (s) => String(s || '').toLowerCase().replace(/\.[a-z0-9]+$/, '').replace(/[^a-z0-9]+/g, '-');
const byNormalized = new Map();
for (const a of index) if (a.filename) byNormalized.set(normalize(a.filename), a);

return $input.all().map((item) => {
  const r = { ...item.json };
  if (r.none) return { json: { ...r, route: 'none' } };

  let resolved = null;
  if (r.asset_match) {
    resolved = byName.get(String(r.asset_match).toLowerCase()) || byNormalized.get(normalize(r.asset_match)) || null;
  }
  const named = r.subject_kind === 'named_property' || r.subject_kind === 'brand_element' || r.purpose === 'decorative_element';

  if (resolved && resolved.url) {
    r.route = 'workdrive';
    r.resolved = { url: resolved.url, id: resolved.id || resolved.workdrive_file_id || '', filename: resolved.filename || '', width: resolved.width, height: resolved.height };
  } else if (named) {
    r.route = 'placeholder';
    if (r.source === 'pexels') r.overridden = 'a named property may not use a stock photo';
  } else if (r.query) {
    r.route = 'pexels';
  } else {
    r.route = 'placeholder';
    r.overridden = 'no query for a stock search';
  }
  return { json: r };
});

// Select assets — runs once over the merged items. Turns search results into the
// asset map the compiler expects and the audit records the job keeps.
//
// The HTTP node replaced each Pexels item's data with the API response, so the requirement
// each result belongs to is recovered through n8n's paired-item chain (`itemMatching`).
// Photos are scored for relevance against the query, checked for orientation and size, and
// never reused within a deck; when nothing acceptable comes back the slot becomes a
// placeholder with a warning rather than a wrong picture.
const items = $input.all();
const assets = {};
const assetUsage = [];
const warnings = [];
const used = new Set();
const now = new Date().toISOString();

const tokens = (s) => String(s || '').toLowerCase().split(/[^a-z0-9]+/).filter((t) => t.length > 2);
const AVOID = /\b(hotel|resort|villa|room|suite|logo|brand|lobby)\b/i;

function pickPhoto(req, photos) {
  const q = new Set(tokens(req.query));
  const landscape = req.orientation !== 'portrait';
  let best = null;
  for (const ph of photos) {
    if (!ph || used.has(ph.id)) continue;
    const w = ph.width || 0, h = ph.height || 1;
    const ratio = w / h;
    if (w < req.minWidth) continue;
    if (landscape ? ratio < 1.25 : ratio > 0.85) continue;
    let score = 0;
    for (const t of tokens(ph.alt)) if (q.has(t)) score += 2;
    if (AVOID.test(ph.alt || '')) score -= 3;
    score += Math.min(3, w / 2000);
    if (!best || score > best.score) best = { ph, score };
  }
  return best ? best.ph : null;
}

function downloadUrl(req, ph) {
  const src = ph.src || {};
  if (req.orientation === 'portrait') return src.portrait || src.large2x || src.original;
  return src.large2x || src.large || src.original;
}

for (let i = 0; i < items.length; i++) {
  let req;
  try {
    req = $('Route assets').itemMatching(i).json;
  } catch (e) {
    warnings.push('a search result could not be matched to its slide');
    continue;
  }
  if (req.none) continue;
  const ref = `${req.slideId}:${req.purpose}`;
  const res = items[i].json || {};

  if (req.route === 'workdrive' && req.resolved) {
    assets[ref] = { url: req.resolved.url, source: 'workdrive', width: req.resolved.width, height: req.resolved.height };
    assetUsage.push({ slideId: req.slideId, purpose: req.purpose, source: 'workdrive', provider: 'zoho-workdrive', providerImageId: String(req.resolved.id || ''), sourceUrl: req.resolved.url, downloadUrl: req.resolved.url, retrievedAt: now });
    continue;
  }

  if (req.route === 'pexels') {
    const photos = Array.isArray(res.photos) ? res.photos : [];
    const ph = res.error ? null : pickPhoto(req, photos);
    if (ph) {
      used.add(ph.id);
      const url = downloadUrl(req, ph);
      assets[ref] = { url, source: 'pexels', width: ph.width, height: ph.height, credit: `Photo by ${ph.photographer} on Pexels` };
      assetUsage.push({ slideId: req.slideId, purpose: req.purpose, source: 'pexels', provider: 'pexels', providerImageId: String(ph.id), sourceUrl: ph.url, downloadUrl: url, photographer: ph.photographer, licenseUrl: 'https://www.pexels.com/license/', query: req.query, retrievedAt: now });
      continue;
    }
    // Carry the real reason through to the job record: "the search failed" alone sends
    // someone hunting in the wrong place, whereas a code like ERR_INVALID_HTTP_TOKEN names
    // the credential as the culprit.
    const why = res.error ? res.error.message || res.error.code || 'error' : null;
    warnings.push(why
      ? `${req.slideId}: the stock photo search failed (${why}); a placeholder is used`
      : `${req.slideId}: no suitable stock photo for "${req.query}"; a placeholder is used`);
  } else if (req.overridden) {
    warnings.push(`${req.slideId}: ${req.overridden}; a placeholder is used`);
  }

  if (req.purpose === 'decorative_element') continue; // no placeholder for illustrations: simply omitted
  assets[ref] = { url: '', source: 'placeholder' };
  assetUsage.push({ slideId: req.slideId, purpose: req.purpose, source: 'placeholder', retrievedAt: now });
}

return [{ json: { assets, assetUsage, warnings } }];

// Canva result — runs once. Reads what the Canva node returned, or the error item it
// produced when the import failed or timed out, into one shape.
//
// It never throws. A Canva failure is not a failed job: the deck is already built and in the
// bucket, so the job ends as "done" with a warning and the PowerPoint to download, which is
// what the business rules ask for.
const r = $input.first().json || {};
const job = r.job || {};
const design = (job.result && Array.isArray(job.result.designs) && job.result.designs[0]) || {};
const urls = design.urls || {};
const ok = job.status === 'success' && !!design.id;

// n8n puts a string here for some failures and an object for others.
const text = (e) => (!e ? '' : typeof e === 'string' ? e : e.message || e.description || e.code || '');

return [
  {
    json: {
      ok,
      designId: design.id || '',
      editUrl: urls.edit_url || '',
      viewUrl: urls.view_url || '',
      error: ok ? '' : text(r.error) || text(job.error) || 'Canva did not return a design',
    },
  },
];

// Failure — runs once. Every error output in the workflow lands here. It names the node that
// failed and carries a readable message to the app, which shows it under the timeline.
const item = $input.first().json || {};
let jobId = '';
try {
  jobId = $('Context').first().json.jobId;
} catch (e) {
  jobId = (($('Webhook').first().json || {}).body || {}).jobId || '';
}
const raw =
  (item.error && (item.error.message || item.error.description || item.error)) ||
  item.message ||
  (Array.isArray(item.errors) ? item.errors.join('; ') : '') ||
  'Unknown error';
const step = $prevNode.name;

// Which timeline row failed, for the page: map node names onto job statuses.
const STATUS_FOR = [
  [/Claude|manifest/i, 'planning'],
  [/Pexels|asset|requirement|route/i, 'resolving_assets'],
  [/Compile/i, 'compiling'],
  [/Canva|PPTX/i, 'importing'],
];
let status = 'queued';
for (const [re, s] of STATUS_FOR) if (re.test(step)) { status = s; break; }

return [{ json: { jobId, step, status, message: String(raw).slice(0, 500) } }];
